// ollama-relay: reverse-tunnel relay.
// Colab runs a WS client that dials OUT to /connect (Colab egress to workers.dev is plain HTTPS,
// which is why this works where Workers->trycloudflare fetches are edge-blocked with 1016/1033).
// API callers (Agent Zero) hit /v1/* with the proxy key; requests are relayed over the WS
// to the runtime, executed against localhost:11434 there, and streamed back.
export class Tunnel {
  constructor(state, env) {
    this.state = state;
    this.env = env;
    this.pending = new Map(); // id -> {controller, headers, status, started}
    this.nextId = 1;
  }
  _tunnelWs() {
    const sockets = this.state.getWebSockets("tunnel");
    return sockets.length ? sockets[0] : null;
  }
  async fetch(request) {
    const url = new URL(request.url);

    if (url.pathname === "/connect") {
      if (request.headers.get("Upgrade") !== "websocket") return new Response("websocket required", { status: 426 });
      if ((request.headers.get("X-Tunnel-Key") || "") !== this.env.ADMIN_KEY) return new Response("unauthorized", { status: 401 });
      const pair = new WebSocketPair();
      this.state.acceptWebSocket(pair[1], ["tunnel"]);
      return new Response(null, { status: 101, webSocket: pair[0] });
    }

    if (url.pathname === "/health") {
      const bearer = (request.headers.get("Authorization") || "").replace(/^Bearer\s+/i, "");
      if (bearer !== this.env.ADMIN_KEY && bearer !== this.env.PROXY_KEY) return new Response("unauthorized", { status: 401 });
      return Response.json({ ok: true, tunnel: Boolean(this._tunnelWs()) });
    }

    const bearer = (request.headers.get("Authorization") || "").replace(/^Bearer\s+/i, "");
    if (bearer !== this.env.PROXY_KEY) return new Response("unauthorized", { status: 401 });

    const ws = this._tunnelWs();
    if (!ws) return new Response("no tunnel client connected", { status: 503 });

    const id = String(this.nextId++);
    const body = request.method === "GET" || request.method === "HEAD" ? null : await request.arrayBuffer();
    const frame = {
      id,
      method: request.method,
      path: url.pathname + url.search,
      headers: { "content-type": request.headers.get("content-type") || "application/json" },
      bodyB64: body ? btoa(String.fromCharCode(...new Uint8Array(body))) : "",
    };
    // Large bodies: send in one string (requests here are small JSON payloads)
    let headResolve;
    const headPromise = new Promise((res) => { headResolve = res; });
    this.pending.set(id, { headResolve, controller: null, started: Date.now() });
    ws.send(JSON.stringify(frame));
    const { status, headers } = await Promise.race([
      headPromise,
      new Promise((res) => setTimeout(() => res({ status: 504, headers: {} }), 60000)),
    ]);
    if (status === 504) { this.pending.delete(id); return new Response("tunnel timeout waiting for head", { status: 504 }); }

    const self = this;
    const stream = new ReadableStream({
      start(controller) {
        const p = self.pending.get(id);
        if (p) p.controller = controller;
      },
      cancel() { self.pending.delete(id); },
    });
    return new Response(stream, { status, headers });
  }
  async webSocketMessage(ws, message) {
    let d;
    try { d = JSON.parse(message); } catch { return; }
    const id = String(d.id);
    const p = this.pending.get(id);
    if (!p) return;
    if (d.type === "head") {
      p.status = d.status || 200;
      p.headers = d.headers || {};
      p.headResolve({ status: p.status, headers: p.headers });
    } else if (d.type === "chunk") {
      if (p.controller) {
        try {
          const bin = Uint8Array.from(atob(d.b64 || ""), (c) => c.charCodeAt(0));
          p.controller.enqueue(bin);
        } catch {}
      }
    } else if (d.type === "end") {
      if (p.controller) { try { p.controller.close(); } catch {} }
      this.pending.delete(id);
    } else if (d.type === "error") {
      if (p.controller) { try { p.controller.error(new Error(d.message || "tunnel error")); } catch {} }
      this.pending.delete(id);
    }
  }
  async webSocketClose(ws) {
    for (const [id, p] of this.pending) {
      if (p.controller) { try { p.controller.error(new Error("tunnel disconnected")); } catch {} }
      this.pending.delete(id);
    }
  }
}

export default {
  async fetch(request, env, ctx) {
    const url = new URL(request.url);
    const bearer = (request.headers.get("Authorization") || "").replace(/^Bearer\s+/i, "");

    if (url.pathname === "/connect") {
      const ns = env.TUNNEL;
      const stub = ns.idFromName("primary");
      return ns.get(stub).fetch(request);
    }
    if (url.pathname === "/health") {
      const ns = env.TUNNEL;
      const stub = ns.idFromName("primary");
      return ns.get(stub).fetch(request);
    }
    // proxy paths -> DO
    const ns = env.TUNNEL;
    const stub = ns.idFromName("primary");
    return ns.get(stub).fetch(request);
  },
};
